mapper.select:
select

from
    eg_repayment_plan
where
    del_flag = '0'
    and contract_code = #{contractCode}
    and plan_date <= #{planDate}
    and exception_type is null
    and recapture_status != #{recaptureStatus}
order by plan_date

with snapshot as (select contract_code, TO_DATE(to_char(plan_date, 'yyyy-MM'),'yyyy-MM') plan_date, sum(service_fee_amortization_rate) service_fee_amortization_rate from eg_repayment_plan_snapshot where contract_code in
#{contractCode}
and del_flag = '0' group by contract_code, to_char(plan_date, 'yyyy-MM')),
current as (select contract_code, TO_DATE(to_char(plan_date, 'yyyy-MM'),'yyyy-MM') plan_date, sum(service_fee_amortization_rate) service_fee_amortization_rate from eg_repayment_plan where contract_code not in (select distinct contract_code from snapshot) and contract_code in
#{contractCode}
and del_flag = '0' group by contract_code, to_char(plan_date, 'yyyy-MM')) select * from snapshot union all select * from current
